window.docContents[47].resolve({"/UD-II___-express___es/#Core-C_________-sem___ntica-natural--UD-II___-express___es":{"contents":"Uma regra de tipos e uma regra de avaliação por construção de Expr. As regras de tipos estão em Typing.expr e as de avaliação em Eval.expr, cada uma no comentário do caso que a implementa. Onde C++17 não especifica a ordem de avaliação, Core C++ avalia da esquerda para a direita.\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Core C++, semântica natural","header":"2. UD II, expressões","id":"/UD-II___-express___es/#Core-C_________-sem___ntica-natural--UD-II___-express___es"}});